from pathlib import Path
import json
from playwright.sync_api import sync_playwright
r=Path('design-html').resolve();results=[]
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe');page=b.new_page(viewport={'width':320,'height':740})
 def go(id):page.goto((r/'pages'/f'{id}.html').as_uri());page.evaluate('document.fonts.ready')
 go('m05-p02');page.locator('.option').nth(1).click();assert page.locator('.option').nth(1).get_attribute('aria-pressed')=='true';assert page.locator('.option').first.evaluate("e=>getComputedStyle(e,'::after').content")=='none';page.locator('.screen').screenshot(path=str(r/'ui-audit/evidence/after/m05-p02-photo-selected.png'));page.locator('#go').click();page.wait_for_url('**/m05-p04.html');results.append('Material choice updates selected state and routes to photo editor')
 go('m05-p03');page.locator('#story').fill('长回忆内容'*100);page.locator('.styles button').nth(1).click();assert page.locator('.styles button').first.get_attribute('aria-pressed')=='false';page.locator('.modes button').nth(1).click();assert page.locator('.modes button').nth(1).get_attribute('aria-pressed')=='true';page.locator('#generate').click();page.wait_for_url('**/m05-p06.html');assert len(page.evaluate("localStorage.getItem('dujia-comic-story')"))==500;results.append('Comic long story, style/mode selection and generate draft routing passed')
 go('m05-p04');page.locator('.photos button').first.click();assert page.locator('#photo-count').inner_text()=='2';page.locator('#story').fill('回忆'*25);assert page.locator('#counter').inner_text()=='50/50';page.locator('.styles button').nth(2).click();assert page.locator('.styles button').nth(2).get_attribute('aria-pressed')=='true';page.locator('.screen').screenshot(path=str(r/'ui-audit/evidence/after/m05-p04-alternate-style.png'));page.locator('#generate').click();page.wait_for_url('**/m05-p06.html');assert len(page.evaluate("localStorage.getItem('dujia-comic-photo-story')"))==50;results.append('Photo deselection count, 50-character counter, alternate style and draft routing passed')
 go('m05-p05');page.locator('.clip').nth(1).click();assert page.locator('.clip').nth(1).get_attribute('aria-current')=='true';page.locator('.moods button').nth(2).click();assert page.locator('.moods button').nth(2).get_attribute('aria-pressed')=='true';page.locator('#play').click();assert page.locator('#toast').is_visible();page.locator('#narration').fill('影片旁白'*100);page.locator('#generate').click();page.wait_for_url('**/m05-p06.html');assert len(page.evaluate("localStorage.getItem('dujia-film-narration')"))==400;results.append('Film clip/mood selection, existing audio demo feedback and narration draft passed')
 go('m05-p08');page.locator('.thumbs button').last.click();assert page.locator('#page-count').inner_text()=='8 / 8';assert page.locator('.thumbs').evaluate('e=>e.scrollLeft')>0;page.locator('#save').click();assert page.evaluate("localStorage.getItem('dujia-comic-saved')")=='true';boxes=page.locator('.save,.share,.retry').evaluate_all('(els)=>els.map(e=>{const r=e.getBoundingClientRect();return {top:r.top,bottom:r.bottom}})');assert boxes[0]['bottom']<=boxes[1]['top'] and boxes[1]['bottom']<=boxes[2]['top'];assert boxes[-1]['bottom']<=page.locator('.screen').bounding_box()['height']+1;results.append('320px last thumbnail accessible by internal scroll; saved state and three non-overlapping footer targets passed')
 go('m05-p09');page.get_by_role('tab',name='影片',exact=True).click();assert page.locator('.work:visible').count()==1;assert page.locator('.work:visible').get_attribute('data-type')=='影片';assert page.locator('.art-cards').evaluate('e=>getComputedStyle(e).backgroundImage')=='none';page.locator('.screen').screenshot(path=str(r/'ui-audit/evidence/after/m05-p09-film-filter.png'));page.get_by_role('tab',name='草稿',exact=True).click();assert page.locator('.work:visible').count()==1;page.get_by_role('tab',name='全部',exact=True).click();assert page.locator('.work:visible').count()==4;results.append('Work filtering removes card image layers together with DOM and restores all four cards')
 go('m05-p10');value='很长的主角印象'*40;page.locator('#appearance').fill(value);page.locator('#save').click();assert page.locator('#toast').is_visible();page.reload();assert page.locator('#appearance').input_value()==value;assert page.evaluate('document.documentElement.scrollWidth')==320;results.append('Long character input save/reload without horizontal growth passed')
 for i in range(1,11):
  id=f'm05-p{i:02}';go(id);page.locator('.screen').screenshot(path=str(r/'ui-audit/evidence/after'/f'{id}-320.png'));page.evaluate("document.documentElement.style.setProperty('--ui-safe-top','44px');document.documentElement.style.setProperty('--ui-safe-bottom','34px')");m=page.evaluate("()=>{const r=document.querySelector('.screen').getBoundingClientRect();return {y:r.y,h:r.height,doc:document.documentElement.scrollHeight,w:document.documentElement.scrollWidth}}");assert m['y']>=44 and m['doc']>=m['h']+77 and m['w']==320,(id,m)
 results.append('All 10 pages at 320px with 44/34px simulated safe area passed')
 page.evaluate('localStorage.clear()');b.close()
(r/'ui-audit/workshop-interaction-results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2),encoding='utf-8');print('\n'.join(results))
